/* ===== Reset & Base ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; font-size: 16px; }
body {
  font-family: 'Inter', 'DM Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  color: #1a1a2e;
  background: #fff;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
a { color: #006CE4; text-decoration: none; }
a:hover { text-decoration: underline; }
img { max-width: 100%; display: block; }
ul { list-style: none; }
button { cursor: pointer; font-family: inherit; }
input, select { font-family: inherit; }

/* ===== Variables ===== */
:root {
  --navy: #003B95;
  --navy-dark: #002870;
  --blue: #006CE4;
  --blue-light: #e8f0fe;
  --gold: #FFB700;
  --gold-dark: #e6a500;
  --white: #ffffff;
  --gray-50: #f8f9fa;
  --gray-100: #f1f3f5;
  --gray-200: #e9ecef;
  --gray-300: #dee2e6;
  --gray-400: #ced4da;
  --gray-500: #adb5bd;
  --gray-600: #6c757d;
  --gray-700: #495057;
  --gray-800: #343a40;
  --gray-900: #212529;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 20px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,.08);
  --shadow-md: 0 4px 12px rgba(0,0,0,.1);
  --shadow-lg: 0 8px 30px rgba(0,0,0,.12);
  --max-width: 1200px;
  --header-height: 64px;
}

/* ===== Typography ===== */
h1 { font-size: 2.25rem; font-weight: 800; line-height: 1.2; }
h2 { font-size: 1.75rem; font-weight: 700; line-height: 1.3; }
h3 { font-size: 1.25rem; font-weight: 600; line-height: 1.4; }
h4 { font-size: 1.1rem; font-weight: 600; }
p { color: var(--gray-700); }
.section-title { margin-bottom: .25rem; }
.section-subtitle { color: var(--gray-600); font-size: .95rem; margin-bottom: 1.5rem; }

/* ===== Layout ===== */
.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }
.section { padding: 48px 0; }
.section--gray { background: var(--gray-50); }
.section--navy { background: var(--navy); color: var(--white); }
.section--navy .section-subtitle,
.section--navy p { color: rgba(255,255,255,.8); }

/* ===== Header ===== */
.site-header {
  background: var(--navy);
  height: var(--header-height);
  position: sticky;
  top: 0;
  z-index: 1000;
  box-shadow: 0 2px 8px rgba(0,59,149,.3);
}
.header-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  height: 100%;
  display: flex;
  align-items: center;
  gap: 32px;
}
.logo {
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--white);
  white-space: nowrap;
  letter-spacing: -.5px;
}
.logo span { color: var(--gold); }
.main-nav { display: flex; gap: 4px; flex: 1; }
.main-nav a {
  color: rgba(255,255,255,.85);
  font-size: .9rem;
  font-weight: 500;
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  transition: background .2s, color .2s;
  white-space: nowrap;
  text-decoration: none;
}
.main-nav a:hover { background: rgba(255,255,255,.12); color: var(--white); text-decoration: none; }
.main-nav a.active { background: rgba(255,255,255,.18); color: var(--white); }
.header-cta {
  background: var(--gold);
  color: var(--gray-900);
  font-size: .85rem;
  font-weight: 700;
  padding: 8px 18px;
  border-radius: var(--radius-sm);
  border: none;
  transition: background .2s;
}
.header-cta:hover { background: var(--gold-dark); }

/* ===== Hero ===== */
.hero {
  background: linear-gradient(135deg, var(--navy) 0%, #0050b3 50%, var(--blue) 100%);
  color: var(--white);
  padding: 60px 0 56px;
}
.hero h1 { margin-bottom: 8px; font-size: 2.5rem; }
.hero .subtitle { font-size: 1.1rem; opacity: .9; margin-bottom: 28px; }

/* Search Form */
.search-form {
  background: var(--gold);
  padding: 6px;
  border-radius: var(--radius-lg);
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  max-width: 960px;
}
.search-form input,
.search-form select {
  flex: 1;
  min-width: 140px;
  padding: 14px 16px;
  border: none;
  border-radius: var(--radius-md);
  font-size: .95rem;
  background: var(--white);
  color: var(--gray-800);
}
.search-form input::placeholder { color: var(--gray-500); }
.search-form .btn-search {
  background: var(--blue);
  color: var(--white);
  font-weight: 700;
  font-size: 1rem;
  padding: 14px 32px;
  border: none;
  border-radius: var(--radius-md);
  transition: background .2s;
  white-space: nowrap;
}
.search-form .btn-search:hover { background: #005bb5; }
.search-extras {
  margin-top: 14px;
  display: flex;
  gap: 20px;
  flex-wrap: wrap;
}
.search-extras label {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: .9rem;
  color: rgba(255,255,255,.9);
  cursor: pointer;
}
.search-extras input[type="checkbox"] { width: 16px; height: 16px; accent-color: var(--gold); }

/* Radio group for packages */
.radio-group {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
  margin-bottom: 16px;
}
.radio-group label {
  background: rgba(255,255,255,.15);
  padding: 10px 18px;
  border-radius: var(--radius-sm);
  font-size: .9rem;
  cursor: pointer;
  transition: background .2s;
  display: flex;
  align-items: center;
  gap: 6px;
}
.radio-group label:hover { background: rgba(255,255,255,.25); }
.radio-group input[type="radio"] { accent-color: var(--gold); }
.radio-group input[type="radio"]:checked + span { font-weight: 600; }

/* ===== Trust Badges ===== */
.trust-badges {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  padding: 36px 0;
}
.trust-badge {
  text-align: center;
  padding: 20px 12px;
}
.trust-badge .badge-icon {
  width: 48px;
  height: 48px;
  margin: 0 auto 12px;
  background: var(--blue-light);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.3rem;
}
.trust-badge h4 { margin-bottom: 4px; font-size: .95rem; }
.trust-badge p { font-size: .82rem; color: var(--gray-600); }

/* ===== Offers ===== */
.offers-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}
.offer-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-md);
  display: flex;
  flex-direction: column;
}
.offer-card--navy { background: var(--navy); color: var(--white); }
.offer-card--gold { background: linear-gradient(135deg, #1a1a2e, #2d2d44); color: var(--white); }
.offer-card .offer-content { padding: 32px; flex: 1; display: flex; flex-direction: column; justify-content: center; }
.offer-card h3 { font-size: 1.4rem; margin-bottom: 10px; color: var(--white); }
.offer-card p { color: rgba(255,255,255,.8); font-size: .92rem; margin-bottom: 20px; }
.offer-card .btn-offer {
  display: inline-block;
  background: var(--gold);
  color: var(--gray-900);
  padding: 10px 22px;
  border-radius: var(--radius-sm);
  font-weight: 700;
  font-size: .9rem;
  transition: background .2s;
  text-decoration: none;
  align-self: flex-start;
}
.offer-card .btn-offer:hover { background: var(--gold-dark); text-decoration: none; }

/* ===== Property Types ===== */
.property-types-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.property-type-chip {
  background: var(--white);
  border: 1px solid var(--gray-300);
  padding: 10px 18px;
  border-radius: 40px;
  font-size: .88rem;
  font-weight: 500;
  color: var(--gray-700);
  transition: all .2s;
  cursor: pointer;
}
.property-type-chip:hover {
  border-color: var(--blue);
  color: var(--blue);
  background: var(--blue-light);
}

/* ===== Tabs ===== */
.tabs-nav {
  display: flex;
  gap: 4px;
  overflow-x: auto;
  padding-bottom: 4px;
  margin-bottom: 24px;
  scrollbar-width: thin;
}
.tabs-nav::-webkit-scrollbar { height: 4px; }
.tabs-nav::-webkit-scrollbar-thumb { background: var(--gray-300); border-radius: 2px; }
.tab-btn {
  background: none;
  border: 1px solid var(--gray-300);
  padding: 10px 20px;
  border-radius: var(--radius-sm);
  font-size: .88rem;
  font-weight: 500;
  color: var(--gray-600);
  white-space: nowrap;
  transition: all .2s;
}
.tab-btn:hover { border-color: var(--blue); color: var(--blue); }
.tab-btn.active {
  background: var(--blue);
  color: var(--white);
  border-color: var(--blue);
}
.tab-content { display: none; }
.tab-content.active { display: block; }

/* ===== Trip Planner ===== */
.trip-planner-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}
.trip-dest-card {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px;
  border-radius: var(--radius-md);
  border: 1px solid var(--gray-200);
  transition: all .2s;
  cursor: pointer;
}
.trip-dest-card:hover { border-color: var(--blue); box-shadow: var(--shadow-sm); }
.trip-dest-card .dest-img {
  width: 64px;
  height: 64px;
  border-radius: var(--radius-sm);
  background: var(--gray-200);
  flex-shrink: 0;
  object-fit: cover;
}
.trip-dest-card .dest-name { font-weight: 600; font-size: .95rem; }
.trip-dest-card .dest-dist { font-size: .82rem; color: var(--gray-500); }

/* ===== Property Cards ===== */
.property-cards-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.property-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: box-shadow .2s;
}
.property-card:hover { box-shadow: var(--shadow-md); }
.property-card .card-img {
  width: 100%;
  height: 180px;
  object-fit: cover;
  background: var(--gray-200);
}
.property-card .card-body { padding: 16px; }
.property-card .card-title { font-size: .95rem; font-weight: 600; margin-bottom: 2px; }
.property-card .card-location { font-size: .82rem; color: var(--gray-500); margin-bottom: 6px; }
.property-card .card-rating {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: .82rem;
  margin-bottom: 8px;
}
.property-card .rating-score {
  background: var(--navy);
  color: var(--white);
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  font-size: .78rem;
  font-weight: 700;
}
.property-card .card-price { font-size: 1.15rem; font-weight: 700; }
.property-card .card-price .original {
  text-decoration: line-through;
  color: var(--gray-500);
  font-size: .9rem;
  font-weight: 400;
  margin-left: 6px;
}
.property-card .card-price .duration {
  font-size: .82rem;
  color: var(--gray-500);
  font-weight: 400;
  display: block;
}

/* ===== Carousel ===== */
.carousel-wrapper { position: relative; }
.carousel-track {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  padding: 4px 0;
}
.carousel-track::-webkit-scrollbar { display: none; }
.carousel-track .property-card { min-width: 280px; flex-shrink: 0; }
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-70%);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: none;
  background: var(--white);
  box-shadow: var(--shadow-md);
  font-size: 1.1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
  transition: box-shadow .2s;
}
.carousel-btn:hover { box-shadow: var(--shadow-lg); }
.carousel-btn--prev { left: -16px; }
.carousel-btn--next { right: -16px; }

/* ===== Trending Destinations ===== */
.trending-list {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}
.trending-chip {
  background: var(--white);
  border: 2px solid var(--gray-200);
  padding: 14px 28px;
  border-radius: var(--radius-lg);
  font-weight: 600;
  font-size: 1rem;
  transition: all .2s;
  cursor: pointer;
}
.trending-chip:hover {
  border-color: var(--blue);
  color: var(--blue);
  transform: translateY(-2px);
  box-shadow: var(--shadow-sm);
}

/* ===== Explore Destinations Grid ===== */
.dest-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
}
.dest-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  position: relative;
  cursor: pointer;
  transition: transform .2s;
}
.dest-card:hover { transform: translateY(-3px); }
.dest-card .dest-img {
  width: 100%;
  height: 140px;
  object-fit: cover;
  background: var(--gray-200);
}
.dest-card .dest-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 12px;
  background: linear-gradient(transparent, rgba(0,0,0,.7));
  color: var(--white);
}
.dest-card .dest-name { font-weight: 600; font-size: .95rem; }
.dest-card .dest-count { font-size: .78rem; opacity: .9; }

/* ===== Weekend Deals ===== */
.deals-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
}
.deal-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: box-shadow .2s;
}
.deal-card:hover { box-shadow: var(--shadow-md); }
.deal-card .card-img {
  width: 100%;
  height: 160px;
  object-fit: cover;
  background: var(--gray-200);
  position: relative;
}
.deal-card .sale-badge {
  position: absolute;
  top: 10px;
  left: 10px;
  background: #c00;
  color: var(--white);
  font-size: .75rem;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 4px;
}
.deal-card .card-body { padding: 14px; }
.deal-card .card-title { font-size: .88rem; font-weight: 600; margin-bottom: 2px; }
.deal-card .card-location { font-size: .78rem; color: var(--gray-500); margin-bottom: 4px; }
.deal-card .card-rating { font-size: .78rem; margin-bottom: 6px; }
.deal-card .card-rating .score {
  background: var(--navy);
  color: var(--white);
  padding: 1px 6px;
  border-radius: 4px;
  font-weight: 700;
  font-size: .72rem;
  margin-right: 4px;
}
.deal-card .card-pricing .original {
  text-decoration: line-through;
  color: var(--gray-500);
  font-size: .82rem;
}
.deal-card .card-pricing .sale {
  font-size: 1.1rem;
  font-weight: 700;
  color: #c00;
  margin-left: 4px;
}
.deal-card .card-pricing .duration {
  font-size: .78rem;
  color: var(--gray-500);
}

/* ===== Homes Guests Love ===== */
.homes-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.home-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: box-shadow .2s;
}
.home-card:hover { box-shadow: var(--shadow-md); }
.home-card .card-img { width: 100%; height: 180px; object-fit: cover; background: var(--gray-200); }
.home-card .card-body { padding: 14px; }
.home-card .card-title { font-size: .92rem; font-weight: 600; margin-bottom: 2px; }
.home-card .card-location { font-size: .78rem; color: var(--gray-500); margin-bottom: 4px; }
.home-card .card-rating { font-size: .78rem; margin-bottom: 6px; }
.home-card .card-rating .score {
  background: var(--navy);
  color: var(--white);
  padding: 1px 6px;
  border-radius: 4px;
  font-weight: 700;
  font-size: .72rem;
  margin-right: 4px;
}
.home-card .card-price { font-size: 1.1rem; font-weight: 700; }

/* ===== Loyalty CTA ===== */
.loyalty-cta {
  text-align: center;
  padding: 48px 24px;
}
.loyalty-cta h2 { color: var(--white); margin-bottom: 6px; }
.loyalty-cta .sub { color: rgba(255,255,255,.8); font-size: 1.1rem; margin-bottom: 8px; }
.loyalty-cta p { color: rgba(255,255,255,.75); margin-bottom: 24px; }
.loyalty-cta .btn-group { display: flex; gap: 12px; justify-content: center; }
.btn-primary {
  background: var(--blue);
  color: var(--white);
  padding: 12px 28px;
  border-radius: var(--radius-sm);
  font-weight: 700;
  font-size: .95rem;
  border: none;
  transition: background .2s;
  text-decoration: none;
}
.btn-primary:hover { background: #005bb5; text-decoration: none; }
.btn-outline {
  background: transparent;
  color: var(--white);
  padding: 12px 28px;
  border-radius: var(--radius-sm);
  font-weight: 700;
  font-size: .95rem;
  border: 2px solid rgba(255,255,255,.4);
  transition: all .2s;
  text-decoration: none;
}
.btn-outline:hover { border-color: var(--white); text-decoration: none; }

/* ===== Popular Links ===== */
.popular-links-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px 32px;
}
.popular-links-list a {
  font-size: .9rem;
  color: var(--gray-700);
  padding: 6px 0;
  border-bottom: 1px solid var(--gray-200);
  transition: color .2s;
}
.popular-links-list a:hover { color: var(--blue); text-decoration: none; }

/* ===== Footer ===== */
.site-footer {
  background: var(--gray-900);
  color: var(--gray-400);
  padding: 48px 0 24px;
  font-size: .85rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 32px;
  margin-bottom: 36px;
}
.footer-col h4 { color: var(--white); font-size: .9rem; margin-bottom: 14px; }
.footer-col a {
  display: block;
  color: var(--gray-400);
  font-size: .82rem;
  padding: 3px 0;
  transition: color .2s;
}
.footer-col a:hover { color: var(--white); text-decoration: none; }
.footer-tagline {
  border-top: 1px solid var(--gray-800);
  padding-top: 20px;
  font-size: .78rem;
  color: var(--gray-600);
}

/* ===== Package Benefits ===== */
.benefits-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.benefit-card {
  text-align: center;
  padding: 32px 24px;
  background: var(--white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
}
.benefit-card .benefit-icon {
  width: 56px;
  height: 56px;
  margin: 0 auto 16px;
  background: var(--blue-light);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
}
.benefit-card h4 { margin-bottom: 8px; }
.benefit-card p { font-size: .88rem; }

/* ===== Rental Companies ===== */
.companies-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 24px;
  justify-content: center;
  align-items: center;
}
.company-logo {
  padding: 16px 28px;
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--gray-700);
  transition: all .2s;
  cursor: pointer;
  min-width: 120px;
  text-align: center;
}
.company-logo:hover { border-color: var(--blue); color: var(--blue); box-shadow: var(--shadow-sm); }

/* ===== Credit Card Promo ===== */
.credit-card-promo {
  background: linear-gradient(135deg, var(--navy), #0050b3);
  color: var(--white);
  padding: 40px;
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}
.credit-card-promo h3 { font-size: 1.3rem; margin-bottom: 8px; }
.credit-card-promo p { color: rgba(255,255,255,.8); font-size: .92rem; }

/* ===== FAQ Accordion ===== */
.faq-list { max-width: 800px; }
.faq-item {
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  margin-bottom: 8px;
  overflow: hidden;
}
.faq-question {
  width: 100%;
  text-align: left;
  padding: 16px 20px;
  background: var(--white);
  border: none;
  font-size: .95rem;
  font-weight: 600;
  color: var(--gray-800);
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: background .2s;
}
.faq-question:hover { background: var(--gray-50); }
.faq-question .arrow {
  transition: transform .2s;
  font-size: .8rem;
  color: var(--gray-500);
}
.faq-item.open .faq-question .arrow { transform: rotate(180deg); }
.faq-answer {
  display: none;
  padding: 0 20px 16px;
  color: var(--gray-600);
  font-size: .9rem;
  line-height: 1.6;
}
.faq-item.open .faq-answer { display: block; }

/* ===== Car Rental Destinations ===== */
.car-dest-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}
.car-dest-card {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px;
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  transition: all .2s;
}
.car-dest-card:hover { border-color: var(--blue); box-shadow: var(--shadow-sm); }
.car-dest-card .dest-img {
  width: 80px;
  height: 60px;
  border-radius: var(--radius-sm);
  object-fit: cover;
  background: var(--gray-200);
  flex-shrink: 0;
}
.car-dest-card .dest-name { font-weight: 600; font-size: .95rem; }
.car-dest-card .dest-locations { font-size: .8rem; color: var(--gray-500); }
.car-dest-card .dest-price { font-size: .88rem; color: var(--blue); font-weight: 600; }

/* ===== Attractions ===== */
.activity-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.activity-card {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  transition: all .2s;
  cursor: pointer;
}
.activity-card:hover { border-color: var(--blue); box-shadow: var(--shadow-sm); }
.activity-card .act-img {
  width: 80px;
  height: 80px;
  border-radius: var(--radius-sm);
  object-fit: cover;
  background: var(--gray-200);
  flex-shrink: 0;
}
.activity-card .act-title { font-weight: 600; font-size: .92rem; }
.activity-card .act-type { font-size: .78rem; color: var(--gray-500); }
.activity-card .act-price { margin-left: auto; font-weight: 700; color: var(--blue); white-space: nowrap; }

.nearby-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}
.nearby-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  position: relative;
  cursor: pointer;
  transition: transform .2s;
}
.nearby-card:hover { transform: translateY(-3px); }
.nearby-card .card-img { width: 100%; height: 140px; object-fit: cover; background: var(--gray-200); }
.nearby-card .card-overlay {
  position: absolute;
  bottom: 0; left: 0; right: 0;
  padding: 12px;
  background: linear-gradient(transparent, rgba(0,0,0,.7));
  color: var(--white);
}
.nearby-card .dest-name { font-weight: 600; font-size: .95rem; }
.nearby-card .dest-count { font-size: .78rem; opacity: .9; }

/* Things to do links */
.things-links {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.things-links a {
  background: var(--white);
  border: 1px solid var(--gray-200);
  padding: 8px 16px;
  border-radius: 40px;
  font-size: .85rem;
  color: var(--gray-700);
  transition: all .2s;
}
.things-links a:hover { border-color: var(--blue); color: var(--blue); text-decoration: none; }

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .trust-badges { grid-template-columns: repeat(2, 1fr); }
  .dest-grid { grid-template-columns: repeat(3, 1fr); }
  .deals-grid { grid-template-columns: repeat(3, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .offers-grid { grid-template-columns: 1fr; }
  .car-dest-grid { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  h1 { font-size: 1.75rem; }
  .hero h1 { font-size: 1.75rem; }
  .section { padding: 32px 0; }
  .trust-badges { grid-template-columns: 1fr 1fr; gap: 16px; }
  .property-cards-row { grid-template-columns: 1fr; }
  .homes-row { grid-template-columns: 1fr; }
  .trip-planner-grid { grid-template-columns: 1fr; }
  .dest-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: repeat(2, 1fr); }
  .benefits-grid { grid-template-columns: 1fr; }
  .nearby-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .popular-links-list { grid-template-columns: 1fr; }
  .search-form { flex-direction: column; }
  .search-form input, .search-form select { min-width: auto; }
  .header-inner { gap: 12px; }
  .main-nav { overflow-x: auto; }
  .credit-card-promo { flex-direction: column; text-align: center; }
  .offers-grid { grid-template-columns: 1fr; }
}

@media (max-width: 480px) {
  .trust-badges { grid-template-columns: 1fr; }
  .dest-grid { grid-template-columns: 1fr; }
  .deals-grid { grid-template-columns: 1fr; }
  .nearby-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .radio-group { flex-direction: column; }
  .header-cta { display: none; }
}

/* ===== Reset & Base ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; font-size: 16px; }
body {
  font-family: 'Inter', 'DM Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  color: #1a1a2e;
  background: #fff;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
a { color: #006CE4; text-decoration: none; }
a:hover { text-decoration: underline; }
img { max-width: 100%; display: block; }
ul { list-style: none; }
button { cursor: pointer; font-family: inherit; }
input, select { font-family: inherit; }

/* ===== Variables ===== */
:root {
  --navy: #003B95;
  --navy-dark: #002870;
  --blue: #006CE4;
  --blue-light: #e8f0fe;
  --gold: #FFB700;
  --gold-dark: #e6a500;
  --white: #ffffff;
  --gray-50: #f8f9fa;
  --gray-100: #f1f3f5;
  --gray-200: #e9ecef;
  --gray-300: #dee2e6;
  --gray-400: #ced4da;
  --gray-500: #adb5bd;
  --gray-600: #6c757d;
  --gray-700: #495057;
  --gray-800: #343a40;
  --gray-900: #212529;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 20px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,.08);
  --shadow-md: 0 4px 12px rgba(0,0,0,.1);
  --shadow-lg: 0 8px 30px rgba(0,0,0,.12);
  --max-width: 1200px;
  --header-height: 64px;
}

/* ===== Typography ===== */
h1 { font-size: 2.25rem; font-weight: 800; line-height: 1.2; }
h2 { font-size: 1.75rem; font-weight: 700; line-height: 1.3; }
h3 { font-size: 1.25rem; font-weight: 600; line-height: 1.4; }
h4 { font-size: 1.1rem; font-weight: 600; }
p { color: var(--gray-700); }
.section-title { margin-bottom: .25rem; }
.section-subtitle { color: var(--gray-600); font-size: .95rem; margin-bottom: 1.5rem; }

/* ===== Layout ===== */
.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }
.section { padding: 48px 0; }
.section--gray { background: var(--gray-50); }
.section--navy { background: var(--navy); color: var(--white); }
.section--navy .section-subtitle,
.section--navy p { color: rgba(255,255,255,.8); }

/* ===== Header ===== */
.site-header {
  background: var(--navy);
  height: var(--header-height);
  position: sticky;
  top: 0;
  z-index: 1000;
  box-shadow: 0 2px 8px rgba(0,59,149,.3);
}
.header-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  height: 100%;
  display: flex;
  align-items: center;
  gap: 32px;
}
.logo {
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--white);
  white-space: nowrap;
  letter-spacing: -.5px;
}
.logo span { color: var(--gold); }
.main-nav { display: flex; gap: 4px; flex: 1; }
.main-nav a {
  color: rgba(255,255,255,.85);
  font-size: .9rem;
  font-weight: 500;
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  transition: background .2s, color .2s;
  white-space: nowrap;
  text-decoration: none;
}
.main-nav a:hover { background: rgba(255,255,255,.12); color: var(--white); text-decoration: none; }
.main-nav a.active { background: rgba(255,255,255,.18); color: var(--white); }
.header-cta {
  background: var(--gold);
  color: var(--gray-900);
  font-size: .85rem;
  font-weight: 700;
  padding: 8px 18px;
  border-radius: var(--radius-sm);
  border: none;
  transition: background .2s;
}
.header-cta:hover { background: var(--gold-dark); }

/* ===== Hero ===== */
.hero {
  background: linear-gradient(135deg, var(--navy) 0%, #0050b3 50%, var(--blue) 100%);
  color: var(--white);
  padding: 60px 0 56px;
}
.hero h1 { margin-bottom: 8px; font-size: 2.5rem; }
.hero .subtitle { font-size: 1.1rem; opacity: .9; margin-bottom: 28px; }

/* Search Form */
.search-form {
  background: var(--gold);
  padding: 6px;
  border-radius: var(--radius-lg);
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  max-width: 960px;
}
.search-form input,
.search-form select {
  flex: 1;
  min-width: 140px;
  padding: 14px 16px;
  border: none;
  border-radius: var(--radius-md);
  font-size: .95rem;
  background: var(--white);
  color: var(--gray-800);
}
.search-form input::placeholder { color: var(--gray-500); }
.search-form .btn-search {
  background: var(--blue);
  color: var(--white);
  font-weight: 700;
  font-size: 1rem;
  padding: 14px 32px;
  border: none;
  border-radius: var(--radius-md);
  transition: background .2s;
  white-space: nowrap;
}
.search-form .btn-search:hover { background: #005bb5; }
.search-extras {
  margin-top: 14px;
  display: flex;
  gap: 20px;
  flex-wrap: wrap;
}
.search-extras label {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: .9rem;
  color: rgba(255,255,255,.9);
  cursor: pointer;
}
.search-extras input[type="checkbox"] { width: 16px; height: 16px; accent-color: var(--gold); }

/* Radio group for packages */
.radio-group {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
  margin-bottom: 16px;
}
.radio-group label {
  background: rgba(255,255,255,.15);
  padding: 10px 18px;
  border-radius: var(--radius-sm);
  font-size: .9rem;
  cursor: pointer;
  transition: background .2s;
  display: flex;
  align-items: center;
  gap: 6px;
}
.radio-group label:hover { background: rgba(255,255,255,.25); }
.radio-group input[type="radio"] { accent-color: var(--gold); }
.radio-group input[type="radio"]:checked + span { font-weight: 600; }

/* ===== Trust Badges ===== */
.trust-badges {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  padding: 36px 0;
}
.trust-badge {
  text-align: center;
  padding: 20px 12px;
}
.trust-badge .badge-icon {
  width: 48px;
  height: 48px;
  margin: 0 auto 12px;
  background: var(--blue-light);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.3rem;
}
.trust-badge h4 { margin-bottom: 4px; font-size: .95rem; }
.trust-badge p { font-size: .82rem; color: var(--gray-600); }

/* ===== Offers ===== */
.offers-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}
.offer-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-md);
  display: flex;
  flex-direction: column;
}
.offer-card--navy { background: var(--navy); color: var(--white); }
.offer-card--gold { background: linear-gradient(135deg, #1a1a2e, #2d2d44); color: var(--white); }
.offer-card .offer-content { padding: 32px; flex: 1; display: flex; flex-direction: column; justify-content: center; }
.offer-card h3 { font-size: 1.4rem; margin-bottom: 10px; color: var(--white); }
.offer-card p { color: rgba(255,255,255,.8); font-size: .92rem; margin-bottom: 20px; }
.offer-card .btn-offer {
  display: inline-block;
  background: var(--gold);
  color: var(--gray-900);
  padding: 10px 22px;
  border-radius: var(--radius-sm);
  font-weight: 700;
  font-size: .9rem;
  transition: background .2s;
  text-decoration: none;
  align-self: flex-start;
}
.offer-card .btn-offer:hover { background: var(--gold-dark); text-decoration: none; }

/* ===== Property Types ===== */
.property-types-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.property-type-chip {
  background: var(--white);
  border: 1px solid var(--gray-300);
  padding: 10px 18px;
  border-radius: 40px;
  font-size: .88rem;
  font-weight: 500;
  color: var(--gray-700);
  transition: all .2s;
  cursor: pointer;
}
.property-type-chip:hover {
  border-color: var(--blue);
  color: var(--blue);
  background: var(--blue-light);
}

/* ===== Tabs ===== */
.tabs-nav {
  display: flex;
  gap: 4px;
  overflow-x: auto;
  padding-bottom: 4px;
  margin-bottom: 24px;
  scrollbar-width: thin;
}
.tabs-nav::-webkit-scrollbar { height: 4px; }
.tabs-nav::-webkit-scrollbar-thumb { background: var(--gray-300); border-radius: 2px; }
.tab-btn {
  background: none;
  border: 1px solid var(--gray-300);
  padding: 10px 20px;
  border-radius: var(--radius-sm);
  font-size: .88rem;
  font-weight: 500;
  color: var(--gray-600);
  white-space: nowrap;
  transition: all .2s;
}
.tab-btn:hover { border-color: var(--blue); color: var(--blue); }
.tab-btn.active {
  background: var(--blue);
  color: var(--white);
  border-color: var(--blue);
}
.tab-content { display: none; }
.tab-content.active { display: block; }

/* ===== Trip Planner ===== */
.trip-planner-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}
.trip-dest-card {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px;
  border-radius: var(--radius-md);
  border: 1px solid var(--gray-200);
  transition: all .2s;
  cursor: pointer;
}
.trip-dest-card:hover { border-color: var(--blue); box-shadow: var(--shadow-sm); }
.trip-dest-card .dest-img {
  width: 64px;
  height: 64px;
  border-radius: var(--radius-sm);
  background: var(--gray-200);
  flex-shrink: 0;
  object-fit: cover;
}
.trip-dest-card .dest-name { font-weight: 600; font-size: .95rem; }
.trip-dest-card .dest-dist { font-size: .82rem; color: var(--gray-500); }

/* ===== Property Cards ===== */
.property-cards-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.property-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: box-shadow .2s;
}
.property-card:hover { box-shadow: var(--shadow-md); }
.property-card .card-img {
  width: 100%;
  height: 180px;
  object-fit: cover;
  background: var(--gray-200);
}
.property-card .card-body { padding: 16px; }
.property-card .card-title { font-size: .95rem; font-weight: 600; margin-bottom: 2px; }
.property-card .card-location { font-size: .82rem; color: var(--gray-500); margin-bottom: 6px; }
.property-card .card-rating {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: .82rem;
  margin-bottom: 8px;
}
.property-card .rating-score {
  background: var(--navy);
  color: var(--white);
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  font-size: .78rem;
  font-weight: 700;
}
.property-card .card-price { font-size: 1.15rem; font-weight: 700; }
.property-card .card-price .original {
  text-decoration: line-through;
  color: var(--gray-500);
  font-size: .9rem;
  font-weight: 400;
  margin-left: 6px;
}
.property-card .card-price .duration {
  font-size: .82rem;
  color: var(--gray-500);
  font-weight: 400;
  display: block;
}

/* ===== Carousel ===== */
.carousel-wrapper { position: relative; }
.carousel-track {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  padding: 4px 0;
}
.carousel-track::-webkit-scrollbar { display: none; }
.carousel-track .property-card { min-width: 280px; flex-shrink: 0; }
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-70%);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: none;
  background: var(--white);
  box-shadow: var(--shadow-md);
  font-size: 1.1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
  transition: box-shadow .2s;
}
.carousel-btn:hover { box-shadow: var(--shadow-lg); }
.carousel-btn--prev { left: -16px; }
.carousel-btn--next { right: -16px; }

/* ===== Trending Destinations ===== */
.trending-list {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}
.trending-chip {
  background: var(--white);
  border: 2px solid var(--gray-200);
  padding: 14px 28px;
  border-radius: var(--radius-lg);
  font-weight: 600;
  font-size: 1rem;
  transition: all .2s;
  cursor: pointer;
}
.trending-chip:hover {
  border-color: var(--blue);
  color: var(--blue);
  transform: translateY(-2px);
  box-shadow: var(--shadow-sm);
}

/* ===== Explore Destinations Grid ===== */
.dest-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
}
.dest-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  position: relative;
  cursor: pointer;
  transition: transform .2s;
}
.dest-card:hover { transform: translateY(-3px); }
.dest-card .dest-img {
  width: 100%;
  height: 140px;
  object-fit: cover;
  background: var(--gray-200);
}
.dest-card .dest-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 12px;
  background: linear-gradient(transparent, rgba(0,0,0,.7));
  color: var(--white);
}
.dest-card .dest-name { font-weight: 600; font-size: .95rem; }
.dest-card .dest-count { font-size: .78rem; opacity: .9; }

/* ===== Weekend Deals ===== */
.deals-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
}
.deal-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: box-shadow .2s;
}
.deal-card:hover { box-shadow: var(--shadow-md); }
.deal-card .card-img {
  width: 100%;
  height: 160px;
  object-fit: cover;
  background: var(--gray-200);
  position: relative;
}
.deal-card .sale-badge {
  position: absolute;
  top: 10px;
  left: 10px;
  background: #c00;
  color: var(--white);
  font-size: .75rem;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 4px;
}
.deal-card .card-body { padding: 14px; }
.deal-card .card-title { font-size: .88rem; font-weight: 600; margin-bottom: 2px; }
.deal-card .card-location { font-size: .78rem; color: var(--gray-500); margin-bottom: 4px; }
.deal-card .card-rating { font-size: .78rem; margin-bottom: 6px; }
.deal-card .card-rating .score {
  background: var(--navy);
  color: var(--white);
  padding: 1px 6px;
  border-radius: 4px;
  font-weight: 700;
  font-size: .72rem;
  margin-right: 4px;
}
.deal-card .card-pricing .original {
  text-decoration: line-through;
  color: var(--gray-500);
  font-size: .82rem;
}
.deal-card .card-pricing .sale {
  font-size: 1.1rem;
  font-weight: 700;
  color: #c00;
  margin-left: 4px;
}
.deal-card .card-pricing .duration {
  font-size: .78rem;
  color: var(--gray-500);
}

/* ===== Homes Guests Love ===== */
.homes-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.home-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: box-shadow .2s;
}
.home-card:hover { box-shadow: var(--shadow-md); }
.home-card .card-img { width: 100%; height: 180px; object-fit: cover; background: var(--gray-200); }
.home-card .card-body { padding: 14px; }
.home-card .card-title { font-size: .92rem; font-weight: 600; margin-bottom: 2px; }
.home-card .card-location { font-size: .78rem; color: var(--gray-500); margin-bottom: 4px; }
.home-card .card-rating { font-size: .78rem; margin-bottom: 6px; }
.home-card .card-rating .score {
  background: var(--navy);
  color: var(--white);
  padding: 1px 6px;
  border-radius: 4px;
  font-weight: 700;
  font-size: .72rem;
  margin-right: 4px;
}
.home-card .card-price { font-size: 1.1rem; font-weight: 700; }

/* ===== Loyalty CTA ===== */
.loyalty-cta {
  text-align: center;
  padding: 48px 24px;
}
.loyalty-cta h2 { color: var(--white); margin-bottom: 6px; }
.loyalty-cta .sub { color: rgba(255,255,255,.8); font-size: 1.1rem; margin-bottom: 8px; }
.loyalty-cta p { color: rgba(255,255,255,.75); margin-bottom: 24px; }
.loyalty-cta .btn-group { display: flex; gap: 12px; justify-content: center; }
.btn-primary {
  background: var(--blue);
  color: var(--white);
  padding: 12px 28px;
  border-radius: var(--radius-sm);
  font-weight: 700;
  font-size: .95rem;
  border: none;
  transition: background .2s;
  text-decoration: none;
}
.btn-primary:hover { background: #005bb5; text-decoration: none; }
.btn-outline {
  background: transparent;
  color: var(--white);
  padding: 12px 28px;
  border-radius: var(--radius-sm);
  font-weight: 700;
  font-size: .95rem;
  border: 2px solid rgba(255,255,255,.4);
  transition: all .2s;
  text-decoration: none;
}
.btn-outline:hover { border-color: var(--white); text-decoration: none; }

/* ===== Popular Links ===== */
.popular-links-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px 32px;
}
.popular-links-list a {
  font-size: .9rem;
  color: var(--gray-700);
  padding: 6px 0;
  border-bottom: 1px solid var(--gray-200);
  transition: color .2s;
}
.popular-links-list a:hover { color: var(--blue); text-decoration: none; }

/* ===== Footer ===== */
.site-footer {
  background: var(--gray-900);
  color: var(--gray-400);
  padding: 48px 0 24px;
  font-size: .85rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 32px;
  margin-bottom: 36px;
}
.footer-col h4 { color: var(--white); font-size: .9rem; margin-bottom: 14px; }
.footer-col a {
  display: block;
  color: var(--gray-400);
  font-size: .82rem;
  padding: 3px 0;
  transition: color .2s;
}
.footer-col a:hover { color: var(--white); text-decoration: none; }
.footer-tagline {
  border-top: 1px solid var(--gray-800);
  padding-top: 20px;
  font-size: .78rem;
  color: var(--gray-600);
}

/* ===== Package Benefits ===== */
.benefits-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.benefit-card {
  text-align: center;
  padding: 32px 24px;
  background: var(--white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
}
.benefit-card .benefit-icon {
  width: 56px;
  height: 56px;
  margin: 0 auto 16px;
  background: var(--blue-light);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
}
.benefit-card h4 { margin-bottom: 8px; }
.benefit-card p { font-size: .88rem; }

/* ===== Rental Companies ===== */
.companies-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 24px;
  justify-content: center;
  align-items: center;
}
.company-logo {
  padding: 16px 28px;
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--gray-700);
  transition: all .2s;
  cursor: pointer;
  min-width: 120px;
  text-align: center;
}
.company-logo:hover { border-color: var(--blue); color: var(--blue); box-shadow: var(--shadow-sm); }

/* ===== Credit Card Promo ===== */
.credit-card-promo {
  background: linear-gradient(135deg, var(--navy), #0050b3);
  color: var(--white);
  padding: 40px;
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}
.credit-card-promo h3 { font-size: 1.3rem; margin-bottom: 8px; }
.credit-card-promo p { color: rgba(255,255,255,.8); font-size: .92rem; }

/* ===== FAQ Accordion ===== */
.faq-list { max-width: 800px; }
.faq-item {
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  margin-bottom: 8px;
  overflow: hidden;
}
.faq-question {
  width: 100%;
  text-align: left;
  padding: 16px 20px;
  background: var(--white);
  border: none;
  font-size: .95rem;
  font-weight: 600;
  color: var(--gray-800);
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: background .2s;
}
.faq-question:hover { background: var(--gray-50); }
.faq-question .arrow {
  transition: transform .2s;
  font-size: .8rem;
  color: var(--gray-500);
}
.faq-item.open .faq-question .arrow { transform: rotate(180deg); }
.faq-answer {
  display: none;
  padding: 0 20px 16px;
  color: var(--gray-600);
  font-size: .9rem;
  line-height: 1.6;
}
.faq-item.open .faq-answer { display: block; }

/* ===== Car Rental Destinations ===== */
.car-dest-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}
.car-dest-card {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px;
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  transition: all .2s;
}
.car-dest-card:hover { border-color: var(--blue); box-shadow: var(--shadow-sm); }
.car-dest-card .dest-img {
  width: 80px;
  height: 60px;
  border-radius: var(--radius-sm);
  object-fit: cover;
  background: var(--gray-200);
  flex-shrink: 0;
}
.car-dest-card .dest-name { font-weight: 600; font-size: .95rem; }
.car-dest-card .dest-locations { font-size: .8rem; color: var(--gray-500); }
.car-dest-card .dest-price { font-size: .88rem; color: var(--blue); font-weight: 600; }

/* ===== Attractions ===== */
.activity-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.activity-card {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  transition: all .2s;
  cursor: pointer;
}
.activity-card:hover { border-color: var(--blue); box-shadow: var(--shadow-sm); }
.activity-card .act-img {
  width: 80px;
  height: 80px;
  border-radius: var(--radius-sm);
  object-fit: cover;
  background: var(--gray-200);
  flex-shrink: 0;
}
.activity-card .act-title { font-weight: 600; font-size: .92rem; }
.activity-card .act-type { font-size: .78rem; color: var(--gray-500); }
.activity-card .act-price { margin-left: auto; font-weight: 700; color: var(--blue); white-space: nowrap; }

.nearby-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}
.nearby-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  position: relative;
  cursor: pointer;
  transition: transform .2s;
}
.nearby-card:hover { transform: translateY(-3px); }
.nearby-card .card-img { width: 100%; height: 140px; object-fit: cover; background: var(--gray-200); }
.nearby-card .card-overlay {
  position: absolute;
  bottom: 0; left: 0; right: 0;
  padding: 12px;
  background: linear-gradient(transparent, rgba(0,0,0,.7));
  color: var(--white);
}
.nearby-card .dest-name { font-weight: 600; font-size: .95rem; }
.nearby-card .dest-count { font-size: .78rem; opacity: .9; }

/* Things to do links */
.things-links {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.things-links a {
  background: var(--white);
  border: 1px solid var(--gray-200);
  padding: 8px 16px;
  border-radius: 40px;
  font-size: .85rem;
  color: var(--gray-700);
  transition: all .2s;
}
.things-links a:hover { border-color: var(--blue); color: var(--blue); text-decoration: none; }

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .trust-badges { grid-template-columns: repeat(2, 1fr); }
  .dest-grid { grid-template-columns: repeat(3, 1fr); }
  .deals-grid { grid-template-columns: repeat(3, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .offers-grid { grid-template-columns: 1fr; }
  .car-dest-grid { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  h1 { font-size: 1.75rem; }
  .hero h1 { font-size: 1.75rem; }
  .section { padding: 32px 0; }
  .trust-badges { grid-template-columns: 1fr 1fr; gap: 16px; }
  .property-cards-row { grid-template-columns: 1fr; }
  .homes-row { grid-template-columns: 1fr; }
  .trip-planner-grid { grid-template-columns: 1fr; }
  .dest-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: repeat(2, 1fr); }
  .benefits-grid { grid-template-columns: 1fr; }
  .nearby-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .popular-links-list { grid-template-columns: 1fr; }
  .search-form { flex-direction: column; }
  .search-form input, .search-form select { min-width: auto; }
  .header-inner { gap: 12px; }
  .main-nav { overflow-x: auto; }
  .credit-card-promo { flex-direction: column; text-align: center; }
  .offers-grid { grid-template-columns: 1fr; }
}

@media (max-width: 480px) {
  .trust-badges { grid-template-columns: 1fr; }
  .dest-grid { grid-template-columns: 1fr; }
  .deals-grid { grid-template-columns: 1fr; }
  .nearby-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .radio-group { flex-direction: column; }
  .header-cta { display: none; }
}

