arguments.command:
cd /app/output && python3 -c "
import html.parser, sys

class HTMLValidator(html.parser.HTMLParser):
    def __init__(self):
        super().__init__()
        self.errors = []
        self.stack = []
        self.void_elements = {'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
    def handle_starttag(self, tag, attrs):
        if tag not in self.void_elements:
            self.stack.append((tag, self.getpos()))
    def handle_endtag(self, tag):
        if tag in self.void_elements:
            return
        if self.stack and self.stack[-1][0] == tag:
            self.stack.pop()
        elif self.stack:
            self.errors.append(f'Mismatched tag: </{tag}> at {self.getpos()}, expected </{self.stack[-1][0]}>')

for fname in ['index.html','packages.html','car-rental.html','attractions.html']:
    v = HTMLValidator()
    v.feed(open(fname).read())
    if v.errors:
        print(f'{fname}: ERRORS')
        for e in v.errors[:5]: print(f'  {e}')
    else:
        print(f'{fname}: OK')
"

